import openpyxl
wb=openpyxl.load_workbook('inputs/sources/fil_01M6JT431ADAA56DGYHN5YC58J.xlsx',data_only=False)
for ws in wb.worksheets:
    print('SHEET',ws.title,ws.dimensions)
    for row in ws.iter_rows(min_row=1,max_row=min(ws.max_row,15),max_col=min(ws.max_column,5)):
        cells=[(c.coordinate,c.value) for c in row if c.value is not None]
        if cells: print(cells)
    print('---')

